(() => {
  const EN = /\b(PLAY|LEVELS|ENDLESS|CLEAR|NEXT|RETRY|MENU|SCORE|COINS|PAUSED|RESUME|RESTART|BEST|FLIPS|RANK|HOLD|RELEASE|HEROES|TONGUES|TRAILS|BUY|EQUIPPED|LATER|PERFECT|WORLD|FLIES|TIME|OVER|SPLASH|JUNGLE|CANDY|VOLCANO|FLIP|DOUBLE|TRIPLE|LOCKED|OPEN|YARN|VINE|SILK|FIRE|BUBBLES|RAINBOW|FROG|TONGUE|FIRST|NEW|RECORD|LANDED|OUCH|CLOSE|CALL|RUN|GET)\b/i;
  const ALLOW = /^(STICKY|FROG|TOP)$/;
  window.__chk = (lang, name) => {
    const a = __game.i18n.audit();
    (window.__aud ||= {})[lang + ' ' + name] = a;
    const eng = [];
    const w = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    for (let n = w.nextNode(); n; n = w.nextNode()) {
      const el = n.parentElement, s = n.nodeValue.trim();
      if (!s || !el || el.closest('script, style, #logo, #langMenu, svg') || !el.checkVisibility?.({ checkOpacity: true, checkVisibilityCSS: true })) continue;
      let hid = false; for (let p = el; p; p = p.parentElement) if (parseFloat(getComputedStyle(p).opacity) < 0.05) { hid = true; break; }
      if (hid) continue;
      for (const tok of s.match(/[A-Za-z]{3,}/g) || []) {
        if (ALLOW.test(tok)) continue;
        if (lang === 'de' || lang === 'es' || lang === 'pt' || lang === 'fr' || lang === 'id' || lang === 'tr') { if (EN.test(tok)) eng.push(tok); } else eng.push(tok);
      }
    }
    a.eng = eng;
    // vertical-only 'box' hits are stickers / pop-ups that straddle their panel edge on purpose (same in English): keep sideways, viewport and scroller hits
    a.overflow = a.overflow.filter((o) => { const m = /^box (-?\d+),(-?\d+):/.exec(o); return !m || +m[1] < -2 || +m[2] < -2; });
    // every data-fit box (buttons, tabs, titles, stickers) must hold its text without clipping, even after shrinking to 55 %
    for (const e of document.querySelectorAll('[data-fit]')) if (e.offsetWidth && e.checkVisibility?.({ checkOpacity: true, checkVisibilityCSS: true }) && (e.scrollWidth > e.clientWidth + 3 || e.scrollHeight > e.clientHeight + 3)) a.overflow.push('fit clipped: ' + (e.id || e.className) + ' ← ' + e.textContent.trim().slice(0, 30));
    return a.lang === lang && !a.overflow.length && !a.keys.length && !a.missing.length && a.translated > 0 && !eng.length;
  };
  return 'ok';
})()
